mapper.select:
SELECT t.id, t.title, t.topic_content as topicContent, t.status, t.del_flag as delFlag, t.create_time as createTime, t.create_by as createBy, t.latestReplyDate, t.replyNum, t.visitNum FROM ( SELECT FROM tb_topic_info info LEFT JOIN tb_topic_reply reply ON info.id = reply.topic_id LEFT JOIN ( SELECT topic_id, COUNT(id) as visitNum FROM tb_topic_visit GROUP BY topic_id ) visit ON info.id = visit.topic_id GROUP BY info.id ) t
AND t.title LIKE CONCAT('%', #{title}, '%')
AND t.status = #{status}
AND t.del_flag = #{delFlag}
AND t.create_by = #{createBy}
ORDER BY t.create_time DESC
